INSERT INTO siniestros_sutran (
  fecha_corte, fecha_siniestro, hora_siniestro, departamento, codigo_via, kilometro, modalidad, fallecidos, heridos
) VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)
ON CONFLICT (fecha_siniestro, hora_siniestro, departamento, codigo_via, kilometro) DO NOTHING;

parameters.jsCode:
const tomtom = $json.flowSegmentData;
const punto = $('Traer puntos de monitoreo').item.json;

const velocidadActual = tomtom.currentSpeed;
const velocidadNormal = tomtom.freeFlowSpeed;
const congestion = ((velocidadNormal - velocidadActual) / velocidadNormal) * 100;

return {
  json: {
    punto_nombre: punto.nombre,
    velocidad_actual: velocidadActual,
    velocidad_normal: velocidadNormal,
    porcentaje_congestion: Number(congestion.toFixed(1)),
    estado: congestion > 30 ? 'Congestionado' : 'Fluido'
  }
};

const body = $('Webhook1').item.json.body;
const sesion = $('Buscar o crear sesión').item.json;

// Palabras que indican que el usuario no tiene/no quiere mandar foto
const textoMsg = (body.mensaje || '').toLowerCase().trim();
const dijoNoTengoFoto = /no tengo foto|sin foto|no hay foto|no tengo imagen/.test(textoMsg);

// 1) Descripción: se actualiza si llega texto y aún no se había guardado,
//    o si el usuario está corrigiendo (siempre se puede sobreescribir con texto nuevo
//    mientras seguimos en estado "recolectando" y el texto no es solo un comando de omitir foto)
let descripcion = sesion.descripcion;
if (textoMsg && !dijoNoTengoFoto) {
  descripcion = body.mensaje;
}

// 2) Imagen: se guarda si llega, o se marca como "omitida" si el usuario lo indicó por texto
let imagen = sesion.imagen_base64;
let imagenOmitida = sesion.imagen_omitida || false;
if (body.imagen_base64) {
  imagen = body.imagen_base64;
  imagenOmitida = false;
}
if (dijoNoTengoFoto) {
  imagenOmitida = true;
}

// 3) Ubicación: se guarda si llega en el mensaje (botón de compartir ubicación del frontend)
let latitude = sesion.latitude;
let longitude = sesion.longitude;
if (body.latitude != null && body.longitude != null) {
  latitude = body.latitude;
  longitude = body.longitude;
}

// Determinar qué falta
const faltaDescripcion = !descripcion;
const faltaImagen = !imagen && !imagenOmitida;
const faltaUbicacion = latitude == null || longitude == null;
const completo = !faltaDescripcion && !faltaImagen && !faltaUbicacion;

return {
  json: {
    session_id: body.session_id,
    descripcion,
    imagen_base64: imagen,
    imagen_omitida: imagenOmitida,
    latitude,
    longitude,
    falta_descripcion: faltaDescripcion,
    falta_imagen: faltaImagen,
    falta_ubicacion: faltaUbicacion,
    completo,
    nuevo_estado: completo ? 'confirmando' : 'recolectando'
  }
};

const c = $json;
const resumen = `Este es tu reporte:\n\n` +
  `📝 Descripción: ${c.descripcion}\n` +
  `📷 Foto: ${c.imagen_base64 ? 'Adjunta' : 'No adjuntada'}\n` +
  `📍 Ubicación: ${c.latitude}, ${c.longitude}\n\n` +
  `¿Confirmas el envío? Responde "sí" para enviarlo o "no" para corregirlo.`;

return { json: { respuesta: resumen, estado: 'confirmando' } };

const c = $json; // salida real de "Actualizar conversación" (columnas de la BD)

const faltaDescripcion = !c.descripcion;
const faltaImagen = !c.imagen_base64 && !c.imagen_omitida;
const faltaUbicacion = c.latitude == null || c.longitude == null;

let pregunta;
if (faltaDescripcion) {
  pregunta = "Cuéntame qué pasó (describe el incidente).";
} else if (faltaImagen) {
  pregunta = "¿Tienes una foto del incidente? Adjúntala, o escribe 'no tengo foto' si no cuentas con una.";
} else if (faltaUbicacion) {
  pregunta = "¿Me compartes tu ubicación?";
} else {
  pregunta = "Cuéntame un poco más sobre el incidente.";
}

return { json: { respuesta: pregunta, estado: 'recolectando' } };

const body = $('Webhook1').item.json.body;
const texto = (body.mensaje || '').toLowerCase().trim();

const esSi = /^(si|sí|confirmo|correcto|dale|ok|okay|de acuerdo)\b/.test(texto);
const esNo = /^(no|cambiar|corregir|incorrecto|editar)\b/.test(texto);

let resultado = 'ambiguo';
if (esSi) resultado = 'confirmado';
else if (esNo) resultado = 'rechazado';

return { json: { resultado } };

// Usamos la fila de conversaciones ya actualizada (trae descripcion, imagen, lat/lon)
const sesion = $('Buscar o crear sesión').item.json;
return {
  json: {
    session_id: sesion.session_id,
    descripcion: sesion.descripcion,
    imagen_base64: sesion.imagen_base64,
    latitude: sesion.latitude,
    longitude: sesion.longitude
  }
};

const riesgo = $('Riesgo histórico').item.json;
const traficoItems = $('Congestión cercana').all();
const trafico = traficoItems.length > 0 ? traficoItems[0].json : null;

const cantidadSiniestros = riesgo.cantidad_siniestros || 0;
const fallecidos = riesgo.total_fallecidos || 0;

let score = Math.min(cantidadSiniestros * 0.5, 6);
if (fallecidos > 0) score += 2;
if (trafico && trafico.porcentaje_congestion > 30) score += 2;
score = Math.min(Math.round(score * 10) / 10, 10);

const contextoTrafico = (trafico && trafico.nombre)
  ? `Congestión cercana: ${trafico.nombre}, ${trafico.porcentaje_congestion}% (${trafico.estado}).`
  : "Sin datos de tráfico cercano.";

const contextoRiesgo = `Histórico: ${cantidadSiniestros} siniestro(s) en 500m (${fallecidos} con fallecidos). Score: ${score}/10.`;

return { json: { score_riesgo: score, contextoTrafico, contextoRiesgo } };

const conv = $('Preparar datos confirmados').item.json;
const { contextoTrafico, contextoRiesgo } = $('Calcular score de riesgo').item.json;

const parts = [
  { text: `Eres un asistente de UrbanPulse que clasifica reportes ciudadanos de incidentes urbanos en Lima, Perú.
Analiza la descripción y la imagen adjunta (si existe) y clasifica el incidente. La prioridad va de 1 a 5, donde 5 es la máxima urgencia.
Evalúa si la imagen es consistente con la descripción. Si NO hay imagen adjunta, responde imagen_consistente: true y observacion_imagen: "Sin imagen adjunta".
Responde con un mensaje breve y amable confirmando el reporte.
Descripción: "${conv.descripcion}"
${contextoTrafico}
${contextoRiesgo}
Considera el tráfico y el riesgo histórico para ajustar la prioridad, y menciónalos brevemente si es relevante.` }
];

if (conv.imagen_base64) {
  parts.push({ inline_data: { mime_type: "image/jpeg", data: conv.imagen_base64 } });
}

return {
  json: {
    contents: [{ parts }],
    generationConfig: {
      responseMimeType: "application/json",
      responseSchema: {
        type: "OBJECT",
        properties: {
          incident_type: { type: "STRING", enum: ["infraestructura_vial","alumbrado_publico","agua_saneamiento","residuos","arbolado_urbano","incendio","otro"] },
          severity: { type: "STRING", enum: ["baja","media","alta"] },
          priority: { type: "INTEGER" },
          mensaje_ciudadano: { type: "STRING" },
          imagen_consistente: { type: "BOOLEAN" },
          observacion_imagen: { type: "STRING" }
        },
        required: ["incident_type","severity","priority","mensaje_ciudadano","imagen_consistente","observacion_imagen"]
      }
    }
  }
};

const respuestaTexto = $json.candidates[0].content.parts[0].text;
const clasificacion = JSON.parse(respuestaTexto);
const conv = $('Preparar datos confirmados').item.json;
const { score_riesgo } = $('Calcular score de riesgo').item.json;

return {
  json: {
    description: conv.descripcion,
    image_url: null,
    incident_type: clasificacion.incident_type,
    severity: clasificacion.severity,
    priority: clasificacion.priority,
    mensaje_ciudadano: clasificacion.mensaje_ciudadano,
    latitude: conv.latitude,
    longitude: conv.longitude,
    score_riesgo,
    imagen_consistente: clasificacion.imagen_consistente,
    observacion_imagen: clasificacion.observacion_imagen
  }
};

const conv = $('Preparar datos confirmados').item.json;
const { contextoTrafico, contextoRiesgo } = $('Calcular score de riesgo').item.json;

const promptTexto = `Eres un asistente de UrbanPulse que clasifica reportes ciudadanos de incidentes urbanos en Lima, Peru.
Analiza la descripcion y la imagen adjunta (si existe) y clasifica el incidente. La prioridad va de 1 a 5, donde 5 es la maxima urgencia.
Evalua si la imagen es consistente con la descripcion. Si NO hay imagen adjunta, responde imagen_consistente: true y observacion_imagen: "Sin imagen adjunta".
Responde SOLO con un JSON valido con estas claves exactas: incident_type (uno de: infraestructura_vial, alumbrado_publico, agua_saneamiento, residuos, arbolado_urbano, incendio, otro), severity (baja|media|alta), priority (numero 1-5), mensaje_ciudadano (texto breve), imagen_consistente (true|false), observacion_imagen (texto).
Descripcion: "${conv.descripcion}"
${contextoTrafico}
${contextoRiesgo}`;

const content = [{ type: "text", text: promptTexto }];
if (conv.imagen_base64) {
  content.push({ type: "image_url", image_url: { url: `data:image/jpeg;base64,${conv.imagen_base64}` } });
}

return {
  json: {
    model: "qwen/qwen3.8-27b",
    messages: [{ role: "user", content }],
    response_format: { type: "json_object" }
  }
};

const respuestaTexto = $json.choices[0].message.content;
const clasificacion = JSON.parse(respuestaTexto);
const conv = $('Preparar datos confirmados').item.json;
const { score_riesgo } = $('Calcular score de riesgo').item.json;

return {
  json: {
    description: conv.descripcion,
    image_url: null,
    incident_type: clasificacion.incident_type,
    severity: clasificacion.severity,
    priority: clasificacion.priority,
    mensaje_ciudadano: clasificacion.mensaje_ciudadano,
    latitude: conv.latitude,
    longitude: conv.longitude,
    score_riesgo,
    imagen_consistente: clasificacion.imagen_consistente,
    observacion_imagen: clasificacion.observacion_imagen
  }
};

const reporte = $json;

return {
  json: {
    reporte,
    model: "models/gemini-embedding-001",
    content: { parts: [{ text: reporte.description }] },
    outputDimensionality: 768
  }
};

const reporte = $('Armar petición embedding').item.json.reporte;
const valores = $json.embedding.values;
const embeddingTexto = `[${valores.join(',')}]`;

return { json: { ...reporte, embedding: embeddingTexto } };

const reporte = $('Preparar reporte').item.json;
const similares = $('Buscar reportes similares').all();

return { json: { ...reporte, reportes_similares: similares.length } };

