parameters.jsCode:
const r = $('Guardar en reports').item.json;
return {
  json: {
    respuesta: r.mensaje_ciudadano,
    estado: 'completado',
    prioridad: r.priority,
    tipo_incidente: r.incident_type,
    score_riesgo: r.score_riesgo
  }
};

const texto = $json.data;
const lineas = texto.split(/\r?\n/).filter(l => l.trim() !== "");
const headers = lineas[0].split(";").map(h => h.trim().toUpperCase());

const vistos = new Set();
const output = [];

for (let i = 1; i < lineas.length; i++) {
  const valores = lineas[i].split(";");
  if (valores.length < headers.length) continue; // fila incompleta, se descarta

  const fila = {};
  headers.forEach((h, idx) => { fila[h] = (valores[idx] || "").trim(); });

  const fecha = fila["FECHA"] || null;
  const departamento = fila["DEPARTAMENTO"] || null;
  if (!fecha || !departamento) continue; // sin datos mínimos, no sirve

  const clave = [fila["FECHA"], fila["HORA"], fila["DEPARTAMENTO"], fila["CODIGO_VÍA"], fila["KILOMETRO"]].join("|");
  if (vistos.has(clave)) continue; // duplicado dentro del mismo archivo, se descarta
  vistos.add(clave);

  output.push({
    json: {
      fecha_corte: fila["FECHA_CORTE"] || null,
      fecha_siniestro: fecha,
      hora_siniestro: fila["HORA"] || null,
      departamento,
      codigo_via: fila["CODIGO_VÍA"] || fila["CODIGO_VIA"] || null,
      kilometro: fila["KILOMETRO"] || null,
      modalidad: fila["MODALIDAD"] || null,
      fallecidos: parseInt(fila["FALLECIDOS"]) || 0,
      heridos: parseInt(fila["HERIDOS"]) || 0
    }
  });
}

return output;
